source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    width = len(grid[0])
    minimum_prefix = max(2, int(width * 0.60 + 0.999999))
    for i in range(len(grid)):
        for j in range(i + 1, len(grid)):
            a, b = grid[i], grid[j]
            first = next((c for c, (x, y) in enumerate(zip(a, b)) if x != y), width)
            if first < minimum_prefix:
                continue
            if all(x == y for x, y in zip(a[:first], b[:first])):
                for c in range(first, width):
                    if a[c] != b[c] and a[c] == background:
                        out[i][c] = 1
                    if a[c] != b[c] and b[c] == background:
                        out[j][c] = 1
    return out
'''
